import { Router } from "express";
import type { FavoritesStore } from "../db/favorites.ts";
import { HttpError } from "../errors.ts";
import type { PokemonService } from "../services/pokemon.ts";

// Match the version-4 UUID generated by crypto.randomUUID() in the browser.
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

// Apply the same ID validation when adding and removing favorites.
function parsePokemonId(value: string): number {
  const pokemonId = Number(value);
  if (!/^\d+$/.test(value) || !Number.isSafeInteger(pokemonId) || pokemonId < 1) {
    throw new HttpError(400, "Pokemon ID must be a positive safe integer");
  }
  return pokemonId;
}

export function createFavoritesRouter(store: FavoritesStore, pokemonService: PokemonService) {
  // app.ts mounts these routes under /api/favorites.
  const router = Router();

  // This identifier groups records by browser; it is not an authentication system.
  router.use((request, _response, next) => {
    const userId = request.get("X-User-Id");
    if (!userId || !UUID_PATTERN.test(userId)) {
      throw new HttpError(400, "A valid X-User-Id UUID is required");
    }
    // Validation succeeded; let Express continue to the matching route below.
    next();
  });

  router.get("/", (request, response) => {
    // Middleware guarantees the header exists; ! narrows the type and lowercase normalizes it.
    const userId = request.get("X-User-Id")!.toLowerCase();
    response.json({ pokemonIds: store.list(userId) });
  });

  router.put("/:pokemonId", async (request, response) => {
    const userId = request.get("X-User-Id")!.toLowerCase();
    const pokemonId = parsePokemonId(request.params.pokemonId);

    // Existing favorites remain readable and repeatable even if PokeAPI is offline.
    if (!store.has(userId, pokemonId)) {
      await pokemonService.getPokemon(String(pokemonId));
    }
    const created = store.add(userId, pokemonId);
    // Report a new record with 201; repeating the same PUT succeeds with 200.
    response.status(created ? 201 : 200).json({ pokemonId, isFavorite: true });
  });

  router.delete("/:pokemonId", (request, response) => {
    const userId = request.get("X-User-Id")!.toLowerCase();
    const pokemonId = parsePokemonId(request.params.pokemonId);
    // Delete is safe to repeat and needs no PokeAPI request, even for a missing row.
    store.remove(userId, pokemonId);
    response.json({ pokemonId, isFavorite: false });
  });

  return router;
}
